  async addTag(id: string, tag: string): Promise<Customer | null> {
    const row = this.visible().find((row) => row.id === id)
    if (row === undefined) return null
    row.tags = [...(row.tags ?? []), tag]
    row.updatedAt = new Date()
    return row
  }

