/** The values each entity was read with, by the stored names of its fields: a change writes only those that differ. */
const loaded = new WeakMap<Product, Record<string, string>>()

/** The fields of an entity a change may write. */
function changeable(entity: Product): Stored {
  return {
    sku: entity.sku,
    title: entity.title,
    price: entity.price,
    stock: entity.stock,
    reference: entity.reference,
    picture: entity.picture,
    related: entity.related,
  }
}

/** The same fields as text, to compare them later. */
const snapshot = (entity: Product): Record<string, string> =>
  Object.fromEntries(Object.entries(changeable(entity)).map(([name, value]) => [name, JSON.stringify(value ?? null)]))

/** The Product of a document; a field it does not have is null. */
function toEntity(document: Stored): Product {
  const entity = Object.assign(new Product(), {
    id: (plain(document._id) ?? null) as string,
    sku: (plain(document.sku) ?? null) as string,
    title: (plain(document.title) ?? null) as string,
    price: (plain(document.price) ?? null) as string,
    stock: (plain(document.stock) ?? null) as number | null,
    reference: (plain(document.reference) ?? null) as string | null,
    picture: (plain(document.picture) ?? null) as Buffer | null,
    related: (plain(document.related) ?? null) as string[] | null,
  })
  loaded.set(entity, snapshot(entity))
  return entity
}

/** The fields of a new document; those left empty are not stored, and take their default. */
function storedValues(entity: Product): Stored {
  const values: Stored = {
    _id: entity.id,
    sku: entity.sku,
    title: entity.title,
    price: entity.price,
    stock: entity.stock,
    reference: entity.reference,
    picture: entity.picture,
    related: entity.related,
  }
  return Object.fromEntries(Object.entries(values).filter(([, value]) => value !== undefined && value !== null))
}

/** What a change writes and what it removes: only the fields that are not as they were read. */
function changesOf(entity: Product): { $set: Stored; $unset: Stored } {
  const before = loaded.get(entity)
  const $set: Stored = {}
  const $unset: Stored = {}
  for (const [name, value] of Object.entries(changeable(entity))) {
    if (before?.[name] === JSON.stringify(value ?? null)) continue
    if (value === undefined || value === null) $unset[name] = ''
    else $set[name] = value
  }
  return { $set, $unset }
}

/** Keeps products documents in the database, through Mongoose. Every write is stored at once. */
export class MongoProductRepository implements ProductRepository {
  constructor(
    private readonly db: Db,
    private readonly session: ClientSession | null = null,
  ) {}

  /** The row with this primary key, or null. */
  async findById(id: string): Promise<Product | null> {
    if (!isObjectId(id)) return null
    const foundDocument = await this.db.models.products.findOne({ _id: id }).session(this.session).lean<Stored>()
    return foundDocument === null ? null : toEntity(foundDocument)
  }

  /** At most `limit` rows from `offset`, by primary key, and how many there are. */
  async list(offset: number = 0, limit: number = 50): Promise<Page<Product>> {
    const documents = await this.db.models.products.find({}).sort({ _id: 1 }).skip(offset).limit(limit).session(this.session).lean<Stored[]>()
    const total = await this.db.models.products.countDocuments({}).session(this.session)
    return { items: documents.map(toEntity), total, offset, limit }
  }

  /** The row with this sku, or null. */
  async findBySku(sku: string): Promise<Product | null> {
    const foundDocument = await this.db.models.products.findOne({ sku }).session(this.session).lean<Stored>()
    return foundDocument === null ? null : toEntity(foundDocument)
  }

  /** Rows with this title, by primary key. */
  async findAllByTitle(title: string): Promise<Product[]> {
    return (await this.db.models.products.find({ title }).sort({ _id: 1 }).session(this.session).lean<Stored[]>()).map(toEntity)
  }

  /** Stores a new row; the values the database fills are read back. */
  async insert(entity: Product): Promise<Product> {
    try {
      const [document] = await this.db.models.products.create([storedValues(entity)], { session: this.session ?? undefined })
      const stored = toEntity(document.toObject() as Stored)
      Object.assign(entity, stored)
      loaded.set(entity, loaded.get(stored)!)
      return entity
    } catch (error) {
      throw refusal('Product', error)
    }
  }

  /** Stores the changes made to a row read from this repository. */
  async update(entity: Product): Promise<Product> {
    try {
      await this.db.models.products.updateOne({ _id: entity.id }, changesOf(entity), { session: this.session ?? undefined, runValidators: true, timestamps: false })
    } catch (error) {
      throw refusal('Product', error)
    }
    loaded.set(entity, snapshot(entity))
    return entity
  }

  /** Removes a row read from this repository. */
  async delete(entity: Product): Promise<void> {
    try {
      await this.db.models.products.deleteOne({ _id: entity.id }).session(this.session)
    } catch (error) {
      throw refusal('Product', error)
    }
  }

  /** Adds an item to related, and returns the row as it is then, or null when there is none. */
  async addRelated(id: string, related: string): Promise<Product | null> {
    if (!isObjectId(id)) return null
    let changed: Stored | null
    try {
      changed = await this.db.models.products
        .findOneAndUpdate({ _id: id }, { $push: { related: related } }, { returnDocument: 'after', runValidators: true, timestamps: false })
        .session(this.session)
        .lean<Stored>()
    } catch (error) {
      throw refusal('Product', error)
    }
    return changed === null ? null : toEntity(changed)
  }

  /** Removes an item from related, and returns the row as it is then, or null when there is none. */
  async removeRelated(id: string, related: string): Promise<Product | null> {
    if (!isObjectId(id)) return null
    let changed: Stored | null
    try {
      changed = await this.db.models.products
        .findOneAndUpdate({ _id: id }, { $pull: { related: related } }, { returnDocument: 'after', runValidators: true, timestamps: false })
        .session(this.session)
        .lean<Stored>()
    } catch (error) {
      throw refusal('Product', error)
    }
    return changed === null ? null : toEntity(changed)
  }
}

/** Keeps products rows in memory, for tests and for trying the services without a database. */
export class MemoryProductRepository implements ProductRepository {
  private readonly rows = new Map<string, Product>()

  private visible(): Product[] {
    return [...this.rows.values()].filter((row) => true).sort((a, b) => compareKeys(keyOf(a), keyOf(b)))
  }

  /** The row with this primary key, or null. */
  async findById(id: string): Promise<Product | null> {
    return this.visible().find((row) => row.id === id) ?? null
  }

  /** At most `limit` rows from `offset`, by primary key, and how many there are. */
  async list(offset: number = 0, limit: number = 50): Promise<Page<Product>> {
    const rows = this.visible()
    return { items: rows.slice(offset, offset + limit), total: rows.length, offset, limit }
  }

  /** The row with this sku, or null. */
  async findBySku(sku: string): Promise<Product | null> {
    return this.visible().find((row) => row.sku === sku) ?? null
  }

  /** Rows with this title, by primary key. */
  async findAllByTitle(title: string): Promise<Product[]> {
    return this.visible().filter((row) => row.title === title)
  }

  /** Stores a new row; the values the database fills are read back. */
  async insert(entity: Product): Promise<Product> {
    if (entity.id === undefined) entity.id = randomBytes(12).toString('hex')
    if (entity.stock === undefined) entity.stock = 0
    this.rows.set(JSON.stringify(keyOf(entity)), entity)
    return entity
  }

  /** Stores the changes made to a row read from this repository. */
  async update(entity: Product): Promise<Product> {
    this.rows.set(JSON.stringify(keyOf(entity)), entity)
    return entity
  }

  /** Removes a row read from this repository. */
  async delete(entity: Product): Promise<void> {
    this.rows.delete(JSON.stringify(keyOf(entity)))
  }

  /** Adds an item to related, and returns the row as it is then, or null when there is none. */
  async addRelated(id: string, related: string): Promise<Product | null> {
    const row = this.visible().find((row) => row.id === id)
    if (row === undefined) return null
    row.related = [...(row.related ?? []), related]
    return row
  }

  /** Removes an item from related, and returns the row as it is then, or null when there is none. */
  async removeRelated(id: string, related: string): Promise<Product | null> {
    const row = this.visible().find((row) => row.id === id)
    if (row === undefined) return null
    row.related = (row.related ?? []).filter((item) => item !== related)
    return row
  }
}

