/** Tests of the "countries" table. */
import { describe, expect, it } from 'vitest'
import { useTestDatabase } from './database.js'
import { addCountry } from './factories.js'

/** The repositories over the test database, opened empty for every test */
const mongoUow = useTestDatabase()

describe('countries repository', () => {
  it('is stored and read back', async () => {
    const uow = mongoUow()
    const stored = await addCountry(uow, 1)
    const found = await uow.countries.findByDocumentId(stored._id)
    expect(found).not.toBeNull()
    expect(found!._id).toEqual(stored._id)
    expect(await uow.countries.findById(stored.id)).not.toBeNull()
  })

  it('lists rows by key', async () => {
    const uow = mongoUow()
    await addCountry(uow, 1)
    await addCountry(uow, 2)
    const page = await uow.countries.list(0, 1)
    expect(page.total).toBe(2)
    expect(page.items).toHaveLength(1)
  })

  it('stores the changes', async () => {
    const uow = mongoUow()
    const stored = await addCountry(uow, 1)
    stored.name = 'changed'
    await uow.countries.update(stored)
    const found = await uow.countries.findByDocumentId(stored._id)
    expect(found?.name).toBe('changed')
  })

  it('is deleted', async () => {
    const uow = mongoUow()
    const stored = await addCountry(uow, 1)
    await uow.countries.delete(stored)
    expect(await uow.countries.findByDocumentId(stored._id)).toBeNull()
  })
})

